&lt;!-- DEBUG-VIEW START 1 APPPATH\Views\medicamentos\update.php --&gt;
&lt;div class=&quot;caja-cb&quot;&gt;
  &lt;form&gt;
    &lt;div class=&quot;mb-4&quot;&gt;
      &lt;h4 class=&quot;border-bottom pb-2 mb-3&quot;&gt;Elija lo que quiere modificar&lt;/h4&gt;

